-- IFSI validated external sources batch 3
-- Hemostasis, Thermoregulation, Calcium homeostasis
-- Sources: MedlinePlus, NIH ODS, NCBI Bookshelf

update public.curriculum_lessons
set content='L’hémostase correspond aux mécanismes qui limitent le saignement après une lésion vasculaire. Les plaquettes adhèrent rapidement à la zone lésée et s’agrègent pour former un premier clou plaquettaire. Elles libèrent aussi des médiateurs qui participent à l’activation de la coagulation. Les facteurs de coagulation sont des protéines sanguines qui s’activent en cascade et conduisent notamment à la formation de fibrine, laquelle stabilise le caillot. La plupart des facteurs de coagulation sont produits par le foie. Un déficit plaquettaire ou un déficit en facteurs de coagulation peut augmenter le risque de saignement, tandis qu’une coagulation excessive peut favoriser la formation de thromboses.',
source_files=coalesce(source_files,'[]'::jsonb)||jsonb_build_array(
jsonb_build_object('label','MedlinePlus — Coagulation Factor Tests','url','https://medlineplus.gov/lab-tests/coagulation-factor-tests/','validation','institutional_validated'),
jsonb_build_object('label','MedlinePlus — Blood clot formation','url','https://medlineplus.gov/ency/imagepages/19462.htm','validation','institutional_validated'),
jsonb_build_object('label','MedlinePlus — Platelet Tests','url','https://medlineplus.gov/lab-tests/platelet-tests/','validation','institutional_validated')
),updated_at=now()
where id='bc98f561-3e70-47fd-8ba9-f3781240b12f'::uuid;

update public.curriculum_lessons
set content='La thermorégulation permet de maintenir une température corporelle compatible avec le fonctionnement normal de l’organisme. La sudation aide à refroidir le corps, notamment lorsque la température ambiante augmente ou pendant l’exercice. La transpiration est contrôlée par le système nerveux autonome. Lorsqu’il fait froid, les vaisseaux sanguins superficiels de la peau se contractent afin de réduire les pertes de chaleur et de maintenir la température centrale. À l’inverse, en ambiance chaude, l’augmentation du débit sanguin cutané et la sudation favorisent la dissipation thermique. Une forte humidité réduit l’efficacité du refroidissement par évaporation de la sueur.',
source_files=coalesce(source_files,'[]'::jsonb)||jsonb_build_array(
jsonb_build_object('label','MedlinePlus — Sweating','url','https://medlineplus.gov/ency/article/003218.htm','validation','institutional_validated'),
jsonb_build_object('label','MedlinePlus — Skin layers','url','https://medlineplus.gov/ency/imagepages/8912.htm','validation','institutional_validated'),
jsonb_build_object('label','MedlinePlus — Avoid overheating during exercise','url','https://medlineplus.gov/ency/patientinstructions/000865.htm','validation','institutional_validated')
),updated_at=now()
where id='a7f7db84-5d59-4b88-8e48-65a19afefcd9'::uuid;

update public.curriculum_lessons
set content='La calcémie est étroitement régulée afin de maintenir la concentration de calcium sanguin dans une plage compatible avec le fonctionnement neuromusculaire et cellulaire. La parathormone (PTH), sécrétée par les glandes parathyroïdes, joue un rôle majeur lorsque la calcémie baisse. Elle favorise notamment la mobilisation du calcium osseux, la réabsorption rénale du calcium et la production rénale de calcitriol, forme active de la vitamine D. Le calcitriol augmente notamment l’absorption intestinale du calcium. Lorsque la calcémie remonte, la sécrétion de PTH diminue par rétrocontrôle. La majeure partie du calcium corporel est stockée dans les os, qui constituent un important réservoir.',
source_files=coalesce(source_files,'[]'::jsonb)||jsonb_build_array(
jsonb_build_object('label','NIH Office of Dietary Supplements — Calcium Fact Sheet','url','https://ods.od.nih.gov/factsheets/calcium-HealthProfessional/','validation','institutional_validated'),
jsonb_build_object('label','NIH Office of Dietary Supplements — Vitamin D Fact Sheet','url','https://ods.od.nih.gov/factsheets/vitaminD-HealthProfessional/','validation','institutional_validated'),
jsonb_build_object('label','NCBI Bookshelf — Homeostatic Regulation of Calcium','url','https://www.ncbi.nlm.nih.gov/books/NBK56060/','validation','institutional_reference')
),updated_at=now()
where id='d48b72f7-82ca-4511-8401-61c89630f097'::uuid;

on conflict(id) do nothing;

